  "function_summary": {
    "summary": "pure_eval 是一个纯 Python 工具库，用于在不触发任意代码副作用的前提下，对 Python 抽象语法树（AST）中的表达式节点进行安全求值。它既可以从给定的名称映射中取值，也可以从调用栈帧自动收集变量，常用于调试器、异常分析器或代码检查工具中快速推断表达式值。",
    "categories": [
      {
        "name": "AST 安全求值",
        "description": "通过 Evaluator 类对 ast.expr 节点（Name、Attribute、Subscript、Call、容器、运算符等）进行递归求值；遇到可能触发副作用的调用或属性访问时抛出 CannotEval。",
        "evidence": [
          "pure_eval/core.py:Evaluator",
          "pure_eval/core.py:_handle"
        ]
      },
      {
        "name": "表达式发现与分组",
        "description": "遍历 AST 找出所有可安全求值的表达式，并按结构等价分组，便于在源码中同一表达式多次出现时聚合结果。",
        "evidence": [
          "pure_eval/core.py:find_expressions",
          "pure_eval/core.py:interesting_expressions_grouped",
          "pure_eval/core.py:group_expressions"
        ]
      },
      {
        "name": "无触发属性获取",
        "description": "提供 getattr_static 的自定义实现，在获取属性时绕开描述符协议、__getattr__ 与 __getattribute__，从而避免触发 property 或动态属性中的副作用。",
        "evidence": [
          "pure_eval/my_getattr_static.py:getattr_static"
        ]
      },
      {
        "name": "表达式兴趣过滤",
        "description": "is_expression_interesting 过滤掉字面量、以常规名称引用的变量/属性以及内置函数等“显而易见”的表达式，只保留对调试有价值的结果。",
        "evidence": [
          "pure_eval/core.py:is_expression_interesting"
        ]
      }
    ],
